<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { api, type AiDraft, type BatchReadiness, type ConfigurationImportIssue, type DataQualityReport, type DatasetDefinition, type MappingEntry, type MetricDefinition, type MetricResult, type Perspective, type PnlResult, type PvmResult } from './api'

type View = 'overview' | 'import' | 'result' | 'pvm' | 'tree' | 'ai' | 'config' | 'matrix' | 'unit' | 'forecast' | 'risk' | 'topics'
type Scenario = 'ACT_BGT' | 'ACT_FC' | 'FC_BGT'
const view = ref<View>('overview')
const period = ref('2026-08')
const batchNo = ref('BATCH-202608-BASE-001')
const perspective = ref<Perspective>('BASE')
const scope = ref('ALL')
const currentUser = ref(localStorage.getItem('amoeba.user') || 'local-finance')
const source = ref<'api' | 'demo'>('demo')
const loading = ref(false)
const error = ref('')
const metrics = ref<MetricResult[]>([])
const results = ref<PnlResult[]>([])
const pvmRows = ref<PvmResult[]>([])
const treeRows = ref<MetricResult[]>([])
const aiDraft = ref<AiDraft | null>(null)
const readiness = ref<BatchReadiness | null>(null)
const quality = ref<DataQualityReport | null>(null)
const datasets = ref<DatasetDefinition[]>([])
const selectedDataset = ref('')
const selectedFile = ref<File | null>(null)
const importMessage = ref('')
const configMessage = ref('')
const configMetrics = ref<MetricDefinition[]>([])
const mappingRows = ref<MappingEntry[]>([])
const mappingType = ref('SALES_PROJECT')
const metricForm = ref({ metricCode: '', metricName: '', applicablePerspective: 'ALL', unit: 'CNY', formulaExpression: '', displayOrder: 100, enabled: true, aiSummaryTemplate: '' })
const mappingForm = ref({ type: 'SALES_PROJECT', matchKey: '', mappedValue: '', enabled: true })
const mappingTypes = ['SALES_PROJECT', 'INVENTORY', 'EXPENSE_RULE', 'FX_RATE', 'BASE_GRAIN']
const configImportType = ref('SALES_PROJECT_MAPPING')
const configImportFile = ref<File | null>(null)
const configImportMessage = ref('')
const configIssueRows = ref<ConfigurationImportIssue[]>([])
const configImportTypes = ['SALES_PROJECT_MAPPING', 'INVENTORY_MAPPING', 'EXPENSE_CATEGORY', 'EXPENSE_ALLOCATION', 'FX_RATE', 'BASE_GRAIN', 'USER_PERMISSION', 'METRIC_DEFINITION']
const scenario = ref<Scenario>('ACT_BGT')
const fcVersion = ref('FC-202608-V3 · 正式采用')
const matrixMetric = ref('REVENUE')
const v13MatrixRows = [
  { base: '南昌', product: '106Ah', revenue: [25400, 23600, 24800], gross: [5100, 4700, 4800], profit: [4200, 3800, 3900] },
  { base: '南昌', product: '217Ah', revenue: [13600, 14500, 14100], gross: [2200, 2800, 2500], profit: [1600, 2200, 1900] },
  { base: '宜昌', product: '280Ah', revenue: [11600, 10400, 11200], gross: [2400, 2000, 2200], profit: [2000, 1600, 1800] },
  { base: '义乌', product: '217Ah', revenue: [6800, 7400, 7100], gross: [1000, 1400, 1200], profit: [600, 1000, 800] },
  { base: '泰国', product: '217Ah', revenue: [7300, 8200, 7800], gross: [800, 1400, 1100], profit: [400, 1000, 700] },
]
const p1Topics: Record<string, { name: string; note: string; rows: string[][] }> = {
  inventory: { name: '库龄分析', note: '切片日、账龄起算字段和区间待财经确认。', rows: [['南昌', '106Ah', '3,260万', '72%', '21%', '7%', '正常'], ['义乌', '217Ah', '2,180万', '48%', '31%', '21%', '关注'], ['泰国', '314Ah', '1,460万', '35%', '29%', '36%', '高风险']] },
  operation: { name: '事业部运营费用下钻', note: '运营费用保留完整损益分析；经营分析利润是否剔除由已确认口径控制。', rows: [['储能事业部', '市场运营', '差旅费', '186万', '160万', '+26万', '不利'], ['储能事业部', '平台运营', '服务费', '242万', '250万', '-8万', '有利']] },
  drill: { name: '产品线三级下钻', note: '当前演示路径：产品线→产品/型号→客户项目，正式层级待确认。', rows: [['储能产品线', '280Ah', '项目D', '17,320万', '3,600万', '+1,130万'], ['乘用车产品线', '106Ah', '项目A', '22,400万', '4,300万', '+1,400万']] },
  pvm: { name: 'PVM跨维度强化', note: '筛选只改变当前汇总，不重算正式PVM分母。', rows: [['南昌', '乘用车', '106Ah', '深陶', '项目A', '+194万', '+194万'], ['泰国', '商用车', '217Ah', '上通五菱', '项目C', '-286万', '-286万']] },
  rd: { name: '研发提单分析', note: '提单只提供业务分析线索，不直接改写正式研发费用。', rows: [['RD-260812', '项目A', '106Ah', '已结项', '18天', '86万', '已匹配'], ['RD-260831', '待定项目', '314Ah', '待分派', '12天', '42万', '未匹配']] },
  account: { name: '基地费用 by 科目矩阵', note: '科目层级和管理口径映射待财经冻结。', rows: [['南昌', '820万', '560万', '310万', '228万', '146万', '2,064万'], ['宜昌', '740万', '485万', '286万', '205万', '138万', '1,854万']] },
}

const demoMetrics: MetricResult[] = [
  { code: 'REVENUE', name: '营业收入', actual: 128600, budget: 124800, gap: 3800, aiSummary: '收入较预算提升，主要由义乌与泰国基地贡献。' },
  { code: 'GROSS_PROFIT', name: '毛利', actual: 23400, budget: 25100, gap: -1700, aiSummary: '毛利低于预算，建议下钻材料成本和单位成本。' },
  { code: 'NET_PROFIT', name: '营业利润', actual: 8600, budget: 9200, gap: -600, aiSummary: '营业利润完成率93.5%，费用侧仍有改善空间。' },
  { code: 'PROFIT_RATE', name: '净利率', actual: 0.0669, budget: 0.0737, gap: -0.0068 },
  { code: 'VOLUME', name: '出货电量', actual: 3120, budget: 3030, gap: 90 },
  { code: 'BASE_EXPENSE', name: '基地费用合计', actual: 9800, budget: 9100, gap: 700 },
]
const demoResults: PnlResult[] = [
  { scopeCode: '全域', lines: { VOLUME: 3120, REVENUE: 128600, SALES_COST: 105200, GROSS_PROFIT: 23400, BASE_EXPENSE: 9800, NET_PROFIT: 8600, PROFIT_RATE: 0.0669, GAP_REVENUE: 3800, GAP_NET_PROFIT: -600 } },
  { scopeCode: '义乌基地', lines: { VOLUME: 1020, REVENUE: 44600, SALES_COST: 35800, GROSS_PROFIT: 8800, BASE_EXPENSE: 3200, NET_PROFIT: 4100, PROFIT_RATE: 0.0919, GAP_REVENUE: 1900, GAP_NET_PROFIT: 230 } },
  { scopeCode: '泰国基地', lines: { VOLUME: 760, REVENUE: 31800, SALES_COST: 27200, GROSS_PROFIT: 4600, BASE_EXPENSE: 2600, NET_PROFIT: 1200, PROFIT_RATE: 0.0377, GAP_REVENUE: -420, GAP_NET_PROFIT: -510 } },
]
const demoPvm: PvmResult[] = [
  { scopeCode: '义乌基地', perspective: 'BASE', actualVolume: 1020, budgetVolume: 980, volumeGap: 40, actualRevenue: 44600, budgetRevenue: 42700, revenueGap: 1900, actualSalesCost: 35800, budgetSalesCost: 34200, costGap: 1600, actualGrossProfit: 8800, budgetGrossProfit: 8500, grossProfitGap: 300 },
  { scopeCode: '泰国基地', perspective: 'BASE', actualVolume: 760, budgetVolume: 800, volumeGap: -40, actualRevenue: 31800, budgetRevenue: 32220, revenueGap: -420, actualSalesCost: 27200, budgetSalesCost: 26400, costGap: 800, actualGrossProfit: 4600, budgetGrossProfit: 5820, grossProfitGap: -1220 },
]
const demoAi: AiDraft = { batchNo: batchNo.value, status: 'DRAFT', sections: { 总述: '本期收入完成预算，毛利和利润承压。', 未达标: '泰国基地毛利低于预算，成本GAP为正。', 亮点: '义乌基地量、价均实现正向贡献。', 原因线索: '建议优先核查材料成本、固定制造费用及汇率。', 风险: '海外基地汇率和费用分摊口径需持续监控。', 行动建议: '由基地财务补充异常说明，集团财务确认后发布。' } }

const visiblePnl = computed(() => scope.value === 'ALL' ? results.value : results.value.filter((row) => row.scopeCode === scope.value))
const perspectiveName = computed(() => ({ BASE: '基地视角', PRODUCT_LINE: '产品线视角', BUSINESS_UNIT: '事业部视角' }[perspective.value]))
const title = computed(() => ({ overview: '经营总览', import: '数据批次', result: '损益计算结果', pvm: 'PVM因素分析', tree: '指标树', ai: 'AI经营分析', config: '配置中心', matrix: '事业部经营矩阵', unit: '单位效率分析', forecast: 'FC预测与毛利瀑布', risk: '一页风险提示', topics: 'P1专题分析' }[view.value]))
const scenarioLabel = computed(() => ({ ACT_BGT: 'ACT vs BGT', ACT_FC: 'ACT vs FC', FC_BGT: 'FC vs BGT' }[scenario.value]))
const scenarioPair = (actual: number, budget: number, fc = budget + (actual - budget) * 0.72) => scenario.value === 'ACT_FC' ? [actual, fc] : scenario.value === 'FC_BGT' ? [fc, budget] : [actual, budget]
function scenarioGap(actual: number, budget: number, fc?: number) { const [current, base] = scenarioPair(actual, budget, fc); return { current, base, gap: current - base, rate: base ? (current - base) / Math.abs(base) : null } }
function scenarioText(actual: number, budget: number, fc?: number) { const x = scenarioGap(actual, budget, fc); return `${format('REVENUE', x.gap)} · ${x.rate === null ? '—' : `${(x.rate * 100).toFixed(1)}%`} ${scenarioLabel.value}` }
const activeTopic = ref('inventory')
const activeTopicData = computed(() => p1Topics[activeTopic.value])
function v13MatrixPair(row: typeof v13MatrixRows[number]) { const key = matrixMetric.value === 'GROSS' ? 'gross' : matrixMetric.value === 'PROFIT' ? 'profit' : 'revenue'; const values = row[key]; return scenarioPair(values[0], values[1], values[2]) }
function v13MatrixCell(rows: typeof v13MatrixRows) { const pairs = rows.map(v13MatrixPair); const current = pairs.reduce((sum, pair) => sum + pair[0], 0); const base = pairs.reduce((sum, pair) => sum + pair[1], 0); return { current, gap: current - base } }
function printRisk() { window.print() }

function setUser() { localStorage.setItem('amoeba.user', currentUser.value.trim() || 'local-finance'); currentUser.value = localStorage.getItem('amoeba.user') || 'local-finance' }
function loadDemo() { source.value = 'demo'; metrics.value = demoMetrics; results.value = demoResults; pvmRows.value = demoPvm; treeRows.value = demoMetrics; aiDraft.value = { ...demoAi, batchNo: batchNo.value }; readiness.value = { batchNo: batchNo.value, perspective: perspective.value, readyForCalculation: true, datasets: [{ datasetCode: 'INC_COST', datasetName: '收入成本明细', required: true, present: true, status: 'VALID', issueCount: 0 }, { datasetCode: 'BUDGET', datasetName: '年度预算收入成本', required: true, present: true, status: 'VALID', issueCount: 0 }] }; quality.value = { batchNo: batchNo.value, perspective: perspective.value, status: 'READY', totalDatasetCount: 2, requiredDatasetCount: 2, presentRequiredDatasetCount: 2, validRequiredDatasetCount: 2, issueCount: 0, missingDatasetCodes: [], invalidDatasetCodes: [], datasets: readiness.value.datasets }; datasets.value = [{ code: 'BASE_ACT_INC_COST', name: '基地实际收入成本明细', required: true, fields: [] }, { code: 'BASE_BUD_INC_COST', name: '基地年度预算收入成本', required: true, fields: [] }]; configMetrics.value = demoMetrics.map((m, i) => ({ metricCode: m.code, metricName: m.name, applicablePerspective: 'ALL', unit: m.code.includes('RATE') ? '%' : 'CNY', formulaExpression: `SUM(${m.code})`, displayOrder: (i + 1) * 10, enabled: true, aiSummaryTemplate: m.aiSummary })); mappingRows.value = [{ type: 'SALES_PROJECT', matchKey: '项目A', mappedValue: '产品线一', enabled: true }, { type: 'SALES_PROJECT', matchKey: '项目B', mappedValue: '产品线二', enabled: true }] }
async function load() {
  loading.value = true; error.value = ''
  try {
    if (view.value !== 'import') metrics.value = await api.overview(period.value, perspective.value, scope.value)
    readiness.value = await api.readiness(batchNo.value); quality.value = await api.quality(batchNo.value); datasets.value = await api.datasets(perspective.value); source.value = 'api'
    if (view.value === 'config') { configMetrics.value = await api.metrics(perspective.value, true); mappingRows.value = await api.mappings(mappingType.value, true) }
    if (view.value === 'result') results.value = (await api.result(batchNo.value)).pnls
    if (view.value === 'pvm') pvmRows.value = await api.pvm(batchNo.value)
    if (view.value === 'tree') treeRows.value = await api.metricTree(batchNo.value)
    if (view.value === 'ai') aiDraft.value = await api.ai(batchNo.value)
  } catch (e) { loadDemo(); error.value = `后端暂不可用，已切换脱敏演示数据：${e instanceof Error ? e.message : '请求失败'}` }
  finally { loading.value = false }
}
async function generateAi() { try { aiDraft.value = await api.generateAi(batchNo.value); source.value = 'api' } catch { loadDemo(); error.value = 'AI服务暂不可用，当前展示规则引擎生成的演示草稿。' } }
async function refreshMappings() { try { mappingRows.value = await api.mappings(mappingType.value, true); source.value = 'api' } catch { mappingRows.value = mappingRows.value.filter(row => row.type === mappingType.value) } }
async function saveMetric() { if (!metricForm.value.metricCode || !metricForm.value.metricName || !metricForm.value.formulaExpression) { configMessage.value = '指标编码、名称和公式不能为空。'; return } try { const saved = await api.upsertMetric(metricForm.value); configMetrics.value = [...configMetrics.value.filter(row => row.metricCode !== saved.metricCode), saved].sort((a, b) => a.displayOrder - b.displayOrder); configMessage.value = `指标 ${saved.metricName} 已保存。`; source.value = 'api' } catch (e) { configMessage.value = e instanceof Error ? e.message : '指标保存失败，当前仅更新演示状态。'; const local = { ...metricForm.value }; configMetrics.value = [...configMetrics.value.filter(row => row.metricCode !== local.metricCode), local].sort((a, b) => a.displayOrder - b.displayOrder) } }
async function saveMapping() { if (!mappingForm.value.matchKey || !mappingForm.value.mappedValue) { configMessage.value = '匹配键和值不能为空。'; return } try { const saved = await api.upsertMapping(mappingForm.value); mappingRows.value = [...mappingRows.value.filter(row => !(row.type === saved.type && row.matchKey === saved.matchKey)), saved]; configMessage.value = `映射 ${saved.matchKey} 已保存。`; source.value = 'api' } catch (e) { configMessage.value = e instanceof Error ? e.message : '映射保存失败，当前仅更新演示状态。'; mappingRows.value = [...mappingRows.value.filter(row => !(row.type === mappingForm.value.type && row.matchKey === mappingForm.value.matchKey)), { ...mappingForm.value }] } }
async function disableMapping(row: MappingEntry) { try { await api.disableMapping({ type: row.type, matchKey: row.matchKey }); row.enabled = false; configMessage.value = `映射 ${row.matchKey} 已停用。`; source.value = 'api' } catch { row.enabled = false; configMessage.value = `演示状态：映射 ${row.matchKey} 已停用。` } }
function pickConfigFile(event: Event) { const input = event.target as HTMLInputElement; configImportFile.value = input.files && input.files.length ? input.files[0] : null }
async function uploadConfig() { if (!configImportFile.value) { configImportMessage.value = '请选择基础配置文件。'; return } try { const task = await api.createConfigImport({ type: configImportType.value, fileName: configImportFile.value.name }); await api.uploadConfigImport(task.taskNo, configImportFile.value); const result = await api.validateConfigImport(task.taskNo, configImportFile.value); configIssueRows.value = result.issues; configImportMessage.value = result.status === 'VALID' ? `校验并应用通过：${result.rowCount} 行配置已生效，任务 ${task.taskNo}。` : `校验/应用未通过：${result.issues.length} 个问题，配置未写入，请修正文件后重新创建任务。`; source.value = 'api' } catch (e) { configIssueRows.value = []; configImportMessage.value = e instanceof Error ? e.message : '配置文件上传失败，当前仅保留演示状态。' } }
function pickFile(event: Event) { const input = event.target as HTMLInputElement; selectedFile.value = input.files && input.files.length ? input.files[0] : null }
async function submitImport() {
  if (!selectedDataset.value || !selectedFile.value) { importMessage.value = '请选择数据集并上传 Excel 文件。'; return }
  try { await api.createBatch({ batchNo: batchNo.value, period: period.value, perspective: perspective.value }); } catch { /* 已存在时继续使用当前批次 */ }
  try { const task = await api.createImport(batchNo.value, { datasetCode: selectedDataset.value, fileName: selectedFile.value.name }); await api.validateImport(task.taskNo, selectedFile.value); importMessage.value = `校验完成：${selectedFile.value.name}，请刷新批次完整性。`; await load() } catch (e) { importMessage.value = e instanceof Error ? e.message : '导入失败，已保留当前演示数据。' }
}
function format(code: string, value: number) { if (code.includes('RATE')) return `${(value * 100).toFixed(2)}%`; return new Intl.NumberFormat('zh-CN', { maximumFractionDigits: 2 }).format(value) }
onMounted(loadDemo)
</script>

<template>
  <main class="app-shell">
    <header class="topbar"><div><strong>数智财经</strong><span class="brand-sub">FINANCE INTELLIGENCE</span></div><h1>阿米巴经营分析平台</h1><div class="user-box"><input v-model="currentUser" @keyup.enter="setUser" /><button @click="setUser">切换用户</button></div></header>
    <div class="layout">
      <aside class="sidebar"><div class="side-title">平台工作台</div><button v-for="item in ([['overview','经营总览'],['import','数据批次'],['result','损益结果'],['pvm','PVM因素分析'],['matrix','事业部经营矩阵'],['unit','单位效率分析'],['forecast','FC预测与瀑布'],['risk','一页风险提示'],['topics','P1专题分析'],['tree','指标树'],['ai','AI经营分析'],['config','配置中心']] as [View,string][])" :key="item[0]" :class="['nav-item', { active: view === item[0] }]" @click="view = item[0]; load()">{{ item[1] }}</button><div class="side-note">当前用户<br /><b>{{ currentUser }}</b><br /><span>{{ source === 'api' ? '已连接后端' : '脱敏演示模式' }}</span><br /><em>V1.3 看板优化</em></div></aside>
      <section class="content"><div class="toolbar"><label>期间<select v-model="period"><option>2026-08</option><option>2026-07</option><option>2026-06</option></select></label><label>视角<select v-model="perspective"><option value="BASE">基地视角</option><option value="PRODUCT_LINE">产品线视角</option><option value="BUSINESS_UNIT">事业部视角</option></select></label><label>批次<input v-model="batchNo" /></label><label>范围<select v-model="scope"><option>ALL</option><option>义乌基地</option><option>泰国基地</option></select></label><label>对比口径<select v-model="scenario"><option value="ACT_BGT">ACT vs BGT</option><option value="ACT_FC">ACT vs FC</option><option value="FC_BGT">FC vs BGT</option></select></label><label>FC版本<select v-model="fcVersion"><option>FC-202608-V3 · 正式采用</option><option>FC-202608-V2 · 历史</option></select></label><button class="primary" :disabled="loading" @click="load">{{ loading ? '加载中…' : '刷新分析' }}</button></div>
        <div class="v13-banner"><b>V1.3 看板优化</b><span>绝对GAP · TOP · FC · 风险一页纸</span><span class="v13-tag">{{ scenarioLabel }}</span><small>第8个P0仍待恢复；金额为脱敏演示值</small></div><div v-if="error" class="notice">{{ error }}</div><div class="readiness" :class="readiness?.readyForCalculation ? 'ready' : 'blocked'"><b>批次完整性：</b>{{ readiness?.readyForCalculation ? '已满足计算条件' : '暂不可计算' }}<span v-if="readiness">{{ readiness.datasets.filter(d => d.required && d.present && d.status === 'VALID').length }}/{{ readiness.datasets.filter(d => d.required).length }} 个必需数据集已通过</span><span v-if="quality">· 数据质量 {{ quality.status === 'READY' ? '通过' : '阻断' }}{{ quality.issueCount ? `，${quality.issueCount} 个问题` : '' }}</span></div><div class="breadcrumb">经营分析平台 / {{ title }} · {{ perspectiveName }}</div><h2>{{ title }}</h2>
        <template v-if="view === 'overview'"><div class="cards"><article v-for="m in metrics.slice(0,4)" :key="m.code" class="card"><span>{{ m.name }} · {{ scenario === 'FC_BGT' ? 'FC' : 'ACT' }}</span><strong>{{ format(m.code, scenarioGap(m.actual,m.budget).current) }}</strong><small :class="scenarioGap(m.actual,m.budget).gap >= 0 ? 'positive' : 'negative'">绝对GAP {{ scenarioText(m.actual,m.budget) }}</small></article></div><section class="top-grid"><article class="panel"><div class="panel-head"><h3>有利影响 TOP 3</h3><span>按绝对金额排序</span></div><div v-for="row in [['宜昌·280Ah','+1,130万','+7.9%'],['南昌·106Ah','+980万','+6.1%'],['义乌·储能','+710万','+8.8%']]" :key="row[0]" class="top-row"><b>{{ row[0] }}</b><span class="positive">{{ row[1] }}</span><small>{{ row[2] }}</small></div></article><article class="panel"><div class="panel-head"><h3>不利影响 TOP 3</h3><span>需下钻确认</span></div><div v-for="row in [['泰国·217Ah','-920万','-21.4%'],['南昌·217Ah','-610万','-12.8%'],['义乌·217Ah','-430万','-18.7%']]" :key="row[0]" class="top-row"><b>{{ row[0] }}</b><span class="negative">{{ row[1] }}</span><small>{{ row[2] }}</small></div></article></section><section class="panel"><div class="panel-head"><h3>统一经营指标</h3><span>绝对GAP与百分比GAP · {{ scenarioLabel }}</span></div><table><thead><tr><th>指标</th><th>当前值</th><th>基准值</th><th>绝对GAP</th><th>GAP%</th><th>AI简析</th></tr></thead><tbody><tr v-for="m in metrics" :key="m.code"><td>{{ m.name }}</td><td>{{ format(m.code, scenarioGap(m.actual,m.budget).current) }}</td><td>{{ format(m.code, scenarioGap(m.actual,m.budget).base) }}</td><td :class="scenarioGap(m.actual,m.budget).gap >= 0 ? 'positive' : 'negative'">{{ format(m.code,scenarioGap(m.actual,m.budget).gap) }}</td><td>{{ scenarioGap(m.actual,m.budget).rate === null ? '—' : `${(scenarioGap(m.actual,m.budget).rate * 100).toFixed(1)}%` }}</td><td>{{ m.aiSummary || '—' }}</td></tr></tbody></table></section></template>
        <template v-else-if="view === 'import'"><section class="panel import-panel"><div class="panel-head"><h3>月度数据批次导入</h3><span>收入成本、费用、预算等数据分别上传；校验通过后才可计算</span></div><div class="import-form"><label>数据集<select v-model="selectedDataset"><option value="">请选择数据集</option><option v-for="d in datasets" :key="d.code" :value="d.code">{{ d.name }}{{ d.required ? ' · 必需' : '' }}</option></select></label><label>Excel文件<input type="file" accept=".xlsx,.xls" @change="pickFile" /></label><button class="primary" @click="submitImport">上传并校验</button></div><div v-if="importMessage" class="notice">{{ importMessage }}</div><div class="dataset-list"><div v-for="row in readiness?.datasets" :key="row.datasetCode" class="dataset-row"><span>{{ row.datasetName }}</span><b :class="row.status === 'VALID' ? 'positive' : 'negative'">{{ row.status }}</b><small>{{ row.issueCount ? `${row.issueCount} 个问题` : '无问题' }}</small></div></div></section></template>
        <template v-else-if="view === 'result'"><section class="panel"><div class="panel-head"><h3>财经损益表 · {{ perspectiveName }}</h3><span>数据来源：已确认/发布结果</span></div><table><thead><tr><th>分析对象</th><th>营业收入</th><th>销售成本</th><th>毛利</th><th>基地费用</th><th>营业利润</th><th>净利率</th></tr></thead><tbody><tr v-for="row in visiblePnl" :key="row.scopeCode"><td>{{ row.scopeCode }}</td><td>{{ format('REVENUE',row.lines.REVENUE || 0) }}</td><td>{{ format('SALES_COST',row.lines.SALES_COST || 0) }}</td><td>{{ format('GROSS_PROFIT',row.lines.GROSS_PROFIT || 0) }}</td><td>{{ format('BASE_EXPENSE',row.lines.BASE_EXPENSE || 0) }}</td><td>{{ format('NET_PROFIT',row.lines.NET_PROFIT || 0) }}</td><td>{{ format('PROFIT_RATE',row.lines.PROFIT_RATE || 0) }}</td></tr></tbody></table></section></template>
        <template v-else-if="view === 'pvm'"><section class="panel"><div class="panel-head"><h3>PVM · {{ perspectiveName }}</h3><span>基地、产品线/事业部采用独立逻辑</span></div><table><thead><tr><th>对象</th><th>电量实际/预算</th><th>电量GAP</th><th>收入实际/预算</th><th>收入GAP</th><th>成本GAP</th><th>毛利GAP</th></tr></thead><tbody><tr v-for="row in pvmRows" :key="row.scopeCode"><td>{{ row.scopeCode }}</td><td>{{ row.actualVolume }} / {{ row.budgetVolume }}</td><td :class="row.volumeGap >= 0 ? 'positive' : 'negative'">{{ row.volumeGap }}</td><td>{{ format('REVENUE',row.actualRevenue) }} / {{ format('REVENUE',row.budgetRevenue) }}</td><td :class="row.revenueGap >= 0 ? 'positive' : 'negative'">{{ format('REVENUE',row.revenueGap) }}</td><td>{{ format('SALES_COST',row.costGap) }}</td><td :class="row.grossProfitGap >= 0 ? 'positive' : 'negative'">{{ format('GROSS_PROFIT',row.grossProfitGap) }}</td></tr></tbody></table></section></template>
        <template v-else-if="view === 'tree'"><section class="panel tree"><div class="panel-head"><h3>指标树 · {{ perspectiveName }}</h3><span>按用户范围过滤</span></div><div v-for="m in treeRows" :key="m.code" class="tree-row"><div><b>{{ m.name }}</b><small>{{ m.code }}</small></div><div class="bar"><i :style="{ width: `${Math.min(100, Math.abs(m.budget) ? Math.abs(m.actual/m.budget)*100 : 0)}%` }"></i></div><strong :class="m.gap >= 0 ? 'positive' : 'negative'">{{ format(m.code,m.gap) }}</strong><button @click="error = `${m.name}：${m.aiSummary || '当前指标暂无AI简析'}`">AI简析</button></div></section></template>
        <template v-else-if="view === 'config'"><section class="config-grid"><section class="panel"><div class="panel-head"><h3>指标库配置</h3><span>统一经营总览指标；公式由财经维护</span></div><div class="config-form"><input v-model="metricForm.metricCode" placeholder="指标编码" /><input v-model="metricForm.metricName" placeholder="指标名称" /><select v-model="metricForm.applicablePerspective"><option value="ALL">全部视角</option><option value="BASE">基地</option><option value="PRODUCT_LINE">产品线</option><option value="BUSINESS_UNIT">事业部</option></select><input v-model="metricForm.formulaExpression" placeholder="公式，如 SUM(REVENUE)" /><input v-model.number="metricForm.displayOrder" type="number" placeholder="排序" /><button class="primary" @click="saveMetric">保存指标</button></div><div v-if="configMessage" class="notice">{{ configMessage }}</div><table><thead><tr><th>编码</th><th>指标名称</th><th>适用视角</th><th>公式</th><th>状态</th></tr></thead><tbody><tr v-for="row in configMetrics" :key="row.metricCode"><td>{{ row.metricCode }}</td><td>{{ row.metricName }}</td><td>{{ row.applicablePerspective }}</td><td>{{ row.formulaExpression }}</td><td><span :class="row.enabled ? 'positive' : 'negative'">{{ row.enabled ? '启用' : '停用' }}</span></td></tr></tbody></table></section><section class="panel"><div class="panel-head"><h3>映射关系维护</h3><span>基础配置增量维护；停用不删除历史</span></div><div class="config-form"><select v-model="mappingType" @change="mappingForm.type = mappingType; refreshMappings()"><option v-for="type in mappingTypes" :key="type" :value="type">{{ type }}</option></select><input v-model="mappingForm.matchKey" placeholder="匹配键" /><input v-model="mappingForm.mappedValue" placeholder="映射值" /><button class="primary" @click="saveMapping">保存映射</button></div><table><thead><tr><th>类型</th><th>匹配键</th><th>映射值</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="row in mappingRows" :key="`${row.type}-${row.matchKey}`"><td>{{ row.type }}</td><td>{{ row.matchKey }}</td><td>{{ row.mappedValue }}</td><td>{{ row.enabled ? '启用' : '停用' }}</td><td><button class="link-button" v-if="row.enabled" @click="disableMapping(row)">停用</button></td></tr></tbody></table></section></section><section class="panel config-import-panel"><div class="panel-head"><h3>基础配置导入</h3><span>与月度业务数据导入分离；上传后由对应配置校验任务处理</span></div><div class="config-form"><select v-model="configImportType"><option v-for="type in configImportTypes" :key="type" :value="type">{{ type }}</option></select><input type="file" accept=".xlsx,.xls" @change="pickConfigFile" /><button class="primary" @click="uploadConfig">上传配置文件</button></div><div v-if="configImportMessage" class="notice">{{ configImportMessage }}</div><table v-if="configIssueRows.length" class="issue-table"><thead><tr><th>行号</th><th>字段</th><th>错误</th><th>说明</th><th>原始值</th></tr></thead><tbody><tr v-for="(issue, index) in configIssueRows" :key="`${issue.issueCode}-${issue.rowNo}-${index}`"><td>{{ issue.rowNo || '—' }}</td><td>{{ issue.fieldName || '—' }}</td><td class="negative">{{ issue.issueCode }}</td><td>{{ issue.issueMessage }}</td><td>{{ issue.rawValue || '—' }}</td></tr></tbody></table></section><section class="panel quality-panel"><div class="panel-head"><h3>数据质量摘要</h3><span>导入任务的结构校验与完整性汇总</span></div><div v-if="quality" class="quality-stats"><div><b>{{ quality.validRequiredDatasetCount }}/{{ quality.requiredDatasetCount }}</b><small>必需数据集通过</small></div><div><b>{{ quality.issueCount }}</b><small>校验问题</small></div><div><b>{{ quality.missingDatasetCodes.length }}</b><small>缺失数据集</small></div><div><b>{{ quality.invalidDatasetCodes.length }}</b><small>未通过数据集</small></div></div><p v-if="quality?.missingDatasetCodes.length" class="negative">缺失：{{ quality.missingDatasetCodes.join('、') }}</p><p v-if="quality?.invalidDatasetCodes.length" class="negative">未通过：{{ quality.invalidDatasetCodes.join('、') }}</p><p v-if="quality && quality.status === 'READY'" class="positive">当前批次已具备计算前的数据质量条件。</p></section></template>
        <template v-else-if="view === 'matrix'"><section class="panel"><div class="panel-head"><div><h3>事业部视角：基地 × 产品交叉矩阵</h3><small>经营分析利润 = 收入 - 销售成本 - 经营分析费用；剔除研发、运营、减值</small></div><label class="inline-filter">指标<select v-model="matrixMetric"><option value="REVENUE">收入</option><option value="GROSS">毛利</option><option value="PROFIT">经营分析利润</option></select></label></div><div class="matrix-note">当前为脱敏演示数据。该口径用于经营分析，不替代完整损益表；正式上线前需冻结利润剔除项和基地/产品主数据映射。</div><table><thead><tr><th>基地</th><th>产品</th><th>当前值</th><th>基准值</th><th>绝对GAP</th><th>GAP%</th><th>经营判断</th></tr></thead><tbody><tr v-for="row in v13MatrixRows" :key="`${row.base}-${row.product}`"><td>{{ row.base }}</td><td>{{ row.product }}</td><td>{{ format(matrixMetric, v13MatrixPair(row)[0]) }}</td><td>{{ format(matrixMetric, v13MatrixPair(row)[1]) }}</td><td :class="v13MatrixPair(row)[0] - v13MatrixPair(row)[1] >= 0 ? 'positive' : 'negative'">{{ format(matrixMetric, v13MatrixPair(row)[0] - v13MatrixPair(row)[1]) }}</td><td>{{ v13MatrixPair(row)[1] ? ((v13MatrixPair(row)[0] - v13MatrixPair(row)[1]) / Math.abs(v13MatrixPair(row)[1]) * 100).toFixed(1) + '%' : '—' }}</td><td>{{ v13MatrixPair(row)[0] - v13MatrixPair(row)[1] >= 0 ? '贡献提升' : '需下钻' }}</td></tr><tr class="total-row"><td colspan="2">合计</td><td>{{ format(matrixMetric, v13MatrixCell(v13MatrixRows).current) }}</td><td>—</td><td>{{ format(matrixMetric, v13MatrixCell(v13MatrixRows).gap) }}</td><td>—</td><td>按当前筛选口径汇总</td></tr></tbody></table></section></template>
        <template v-else-if="view === 'unit'"><section class="unit-grid"><article class="panel"><div class="panel-head"><div><h3>线体单位制造费用</h3><small>单位：元 / Wh · 口径待预算组确认</small></div><span class="pending">P0-04 待定义</span></div><table><thead><tr><th>基地</th><th>线体</th><th>制造费用</th><th>产出Wh</th><th>元/Wh</th><th>环比</th></tr></thead><tbody><tr v-for="row in [['南昌','L01','1,860万','86.0万','0.216','+4.2%'],['宜昌','L02','1,420万','72.0万','0.197','-2.1%'],['义乌','L03','980万','51.0万','0.192','+1.8%'],['泰国','L01','760万','32.0万','0.238','+8.6%']]" :key="`${row[0]}-${row[1]}`"><td>{{ row[0] }}</td><td>{{ row[1] }}</td><td>{{ row[2] }}</td><td>{{ row[3] }}</td><td>{{ row[4] }}</td><td :class="row[5].startsWith('+') ? 'negative' : 'positive'">{{ row[5] }}</td></tr></tbody></table><div class="matrix-note">待确认项：分母采用合格产出、良品产出还是入库Wh；制造费用是否包含折旧、能源及线体间接人工。</div></article><article class="panel"><div class="panel-head"><div><h3>YU 指标卡与12个月趋势</h3><small>YU 准确定义尚未冻结</small></div><span class="pending">P0-03 待定义</span></div><div class="yu-card"><b>YU</b><strong>待定义</strong><small>当前不写入正式经营结论</small></div><div class="trend-bars"><i v-for="bar in [42,55,61,58,67,74,69,78,82,76,88,91]" :key="bar" :style="{ height: `${bar}%` }"></i></div><div class="trend-labels"><span>2025-09</span><span>2026-08</span></div><div class="matrix-note">趋势图仅验证交互与版式；待确认 YU 指标定义、数据来源、单位和目标值后接入正式服务。</div></article></section></template>
        <template v-else-if="view === 'forecast'"><section class="panel"><div class="panel-head"><div><h3>FC滚动预测与BGT / ACT三口径</h3><small>当前选择：{{ fcVersion }} · 仅支持结果导入、版本管理与对比</small></div><span class="v13-tag">{{ scenarioLabel }}</span></div><div class="matrix-note">FC 不在平台内在线编制；正式预测由预算/经营系统生成后按版本导入，平台负责校验、冻结、对比与追溯。</div><table><thead><tr><th>指标</th><th>BGT</th><th>ACT</th><th>FC</th><th>ACT-BGT</th><th>ACT-FC</th><th>FC-BGT</th></tr></thead><tbody><tr v-for="row in [['营业收入',124800,128600,127536],['毛利',25100,23400,23876],['经营分析利润',9200,8600,8768],['出货电量',3030,3120,3095]]" :key="row[0]"><td>{{ row[0] }}</td><td>{{ format('REVENUE',row[1]) }}</td><td>{{ format('REVENUE',row[2]) }}</td><td>{{ format('REVENUE',row[3]) }}</td><td :class="row[2]-row[1] >= 0 ? 'positive' : 'negative'">{{ format('REVENUE',row[2]-row[1]) }}</td><td :class="row[2]-row[3] >= 0 ? 'positive' : 'negative'">{{ format('REVENUE',row[2]-row[3]) }}</td><td :class="row[3]-row[1] >= 0 ? 'positive' : 'negative'">{{ format('REVENUE',row[3]-row[1]) }}</td></tr></tbody></table></section><section class="panel waterfall-panel"><div class="panel-head"><h3>单位毛利GAP瀑布拆解</h3><span>演示分解：收入、材料、制造、费用、汇率</span></div><div class="waterfall"><div v-for="step in [['预算单位毛利',0,'base'],['材料成本',-18,'down'],['制造费用',-7,'down'],['产品结构',12,'up'],['汇率',-4,'down'],['实际单位毛利',-17,'total']]" :key="step[0]" class="waterfall-step"><div class="waterfall-bar" :class="step[2]" :style="{ height: `${Math.max(16, Math.abs(step[1]) * 4)}px` }"></div><b>{{ step[1] > 0 ? '+' : '' }}{{ step[1] }}</b><small>{{ step[0] }}</small></div></div><div class="matrix-note">正式版本需关联单位毛利分母、PVM维度和材料/制造/费用科目映射；当前仅验证拆解表达。</div></section></template>
        <template v-else-if="view === 'risk'"><section class="panel risk-print"><div class="panel-head"><div><h3>经营分析风险提示 · 一页纸</h3><small>{{ period }} · {{ perspectiveName }} · {{ scenarioLabel }}</small></div><button class="primary" @click="printRisk">打印 / 导出PDF</button></div><div class="risk-summary"><div><small>总体风险</small><b class="negative">中高</b></div><div><small>需关注事项</small><b>4</b></div><div><small>待确认口径</small><b class="pending">6</b></div><div><small>数据状态</small><b class="positive">已通过</b></div></div><table><thead><tr><th>等级</th><th>领域</th><th>风险/异常</th><th>责任角色</th><th>建议动作</th><th>状态</th></tr></thead><tbody><tr v-for="row in [['高','泰国基地','单位制造费用0.238元/Wh，高于南昌','基地财务','拆分能源、折旧、间接人工','待解释'],['中','利润口径','经营分析利润剔除项尚未冻结','预算组','确认研发/运营/减值口径','待确认'],['中','预测版本','FC-202608-V3与V2存在差异','集团财务','保留版本与采用理由','已登记'],['低','库存','义乌217Ah库龄超过180天占比21%','产品线财务','补充去化计划与责任人','跟进中']]" :key="row[1]"><td><span :class="row[0] === '高' ? 'negative' : row[0] === '中' ? 'warning' : 'positive'">{{ row[0] }}</span></td><td>{{ row[1] }}</td><td>{{ row[2] }}</td><td>{{ row[3] }}</td><td>{{ row[4] }}</td><td>{{ row[5] }}</td></tr></tbody></table><div class="matrix-note">风险阈值与红黄灯规则待预算组确认；本页可打印/导出，但不替代正式风险审批。</div></section></template>
        <template v-else-if="view === 'topics'"><section class="panel"><div class="panel-head"><div><h3>P1专题分析原型</h3><small>{{ activeTopicData.name }} · {{ activeTopicData.note }}</small></div><span class="v13-tag">6项 P1</span></div><div class="topic-nav"><button v-for="key in ['inventory','operation','drill','pvm','rd','account']" :key="key" :class="{ active: activeTopic === key }" @click="activeTopic = key">{{ p1Topics[key].name }}</button></div><table><thead><tr><th v-for="n in 7" :key="n">维度{{ n }}</th></tr></thead><tbody><tr v-for="(row,index) in activeTopicData.rows" :key="index"><td v-for="(cell,cellIndex) in row" :key="cellIndex">{{ cell }}</td><td v-for="n in (7 - row.length)" :key="`${index}-empty-${n}`">—</td></tr></tbody></table><div class="matrix-note">P1 当前为原型入口，待 P0 口径冻结、字段映射与权限范围确认后再进入正式开发。</div></section></template>
        <template v-else><section class="panel ai-panel"><div class="panel-head"><h3>AI经营分析草稿</h3><span>需财经点击生成，集团财务确认后分发</span><button class="primary" @click="generateAi">生成/刷新草稿</button></div><div v-if="aiDraft" class="ai-grid"><article v-for="(text, name) in aiDraft.sections" :key="name"><h4>{{ name }}</h4><p>{{ text }}</p></article></div><div v-else class="empty">暂无草稿，请点击生成。</div></section></template>
      </section>
    </div>
  </main>
</template>

<style>
:root { font-family: Inter, Arial, "Microsoft YaHei", sans-serif; color: #263241; background: #f2f4f7; }
* { box-sizing: border-box; } body { margin: 0; } button, input, select { font: inherit; }
